    "help": {
        "campaignBannerTitle": "¿Qué es una campaña?",
        "campaignBanner": "Una campaña es la entidad principal del rastreador. Recibe tráfico a través de una URL única, lo dirige a través de flujos (reglas) a ofertas y páginas de destino. Cada campaña puede tener múltiples transmisiones con diferentes reglas de orientación, filtros geográficos y pruebas A/B.",
        "offerBannerTitle": "¿Qué es una oferta?",
        "offerBanner": "Una oferta es el destino final al que se envía el tráfico (normalmente la página de un anunciante). Puede ser una URL de redireccionamiento, una inserción de iframe o una página alojada localmente. Cada oferta está asociada con una red de afiliados y realiza un seguimiento de las conversiones y los ingresos.",
        "landingBannerTitle": "¿Qué es una página de destino?",
        "landingBanner": "Una página de destino (prelander) es una página intermedia que se muestra antes de la oferta. Calienta al visitante y aumenta las conversiones. Puedes realizar pruebas A/B de varios aterrizajes en una sola transmisión. Los aterrizajes pueden ser externos (URL) o cargarse como un archivo ZIP.",
        "trafficSourceBannerTitle": "¿Qué es una fuente de tráfico?",
        "trafficSourceBanner": "Una fuente de tráfico representa de dónde proviene su tráfico: redes publicitarias, redes sociales, etc. Configurar una fuente le permite pasar parámetros (ID secundarios, costo, palabras clave) y realizar un seguimiento del ROI por fuente. Utilice plantillas para redes populares.",
        "affiliateNetworkBannerTitle": "¿Qué es una red de afiliados?",
        "affiliateNetworkBanner": "Una red de afiliados es el socio que ofrece ofertas. Agregar una red le permite configurar URL de devolución para el seguimiento automático de conversiones. La red envía una devolución de datos cuando un usuario completa una acción (venta, cliente potencial, etc.).",
        "domainBannerTitle": "Seguimiento de dominios",
        "domainBanner": "Un dominio de seguimiento oculta la URL de seguimiento y hace que los enlaces parezcan naturales. Apunte el registro A de su dominio a la IP del servidor, agréguelo aquí y asígnelo a las campañas. Habilite HTTPS y noindex para una mejor seguridad y protección SEO.",
        "postbackBannerTitle": "¿Cómo funcionan las devoluciones de datos?",
        "postbackBanner": "Una devolución de datos (S2S Postback) es una solicitud HTTP de la red de afiliados a su rastreador cuando se produce una conversión. La URL contiene el ID de clic (subid), el estado y el pago. El rastreador lo compara con el clic original y registra la conversión.",
        "postbackMacros": "Macros disponibles: {subid}: ID de clic, {status}: estado de conversión, {payout}: monto, {tid}: ID de transacción, {currency}: código de moneda.",
        "integrationsBannerTitle": "¿Cómo integrar?",
        "integrationsBanner": "Elija un método de integración según su configuración técnica. Tracking Client (PHP) proporciona funciones completas del lado del servidor (encubrimiento, filtrado de bots). Tracking Client (JS) es más sencillo de instalar. Tracking Pixel funciona para el seguimiento básico de impresiones y conversiones.",
        "conversionsBannerTitle": "Estados de conversión",
        "conversionsBanner": "Cada conversión tiene un estado: cliente potencial: un nuevo cliente potencial, venta: compra confirmada, rechazado: rechazado por el anunciante, depósito: primer depósito (apuestas), registro: registro de usuario. Puede configurar estados personalizados en Configuración.",
        "trendsBannerTitle": "Cómo utilizar análisis",
        "trendsBanner": "Seleccione las métricas para mostrar, establezca el rango de fechas y la agrupación. Utilice filtros para limitar por cualquier campo de clic. El gráfico y la tabla se actualizan en tiempo real. Compare métricas para encontrar patrones; por ejemplo, muchos clics pero un CR bajo pueden indicar problemas en la página de destino.",
        "aliasTooltip": "Identificador corto único para la URL de la campaña. Generado automáticamente, pero se puede cambiar. Utilizado en el enlace de seguimiento.",
        "costModelTooltip": "CPC: pago por clic. CPA: pago por conversión. CPM: pago por 1000 impresiones. RevShare: porcentaje de ingresos. CPuC: por clic único. CPS: por venta.",
        "uniquenessTooltip": "Cómo identificar visitantes únicos. IP: solo por dirección IP. IP+UA — por IP y User-Agent (más preciso). Cookies: cookies del navegador (las más precisas, pero se pueden bloquear).",
        "rotationTooltip": "Peso: distribuye el tráfico proporcionalmente según los valores de peso. Posición: envía todo el tráfico al primer flujo activo y utiliza otros como respaldo.",
        "redirectTypeTooltip": "Redireccionamiento: redireccionamiento 302 estándar (rápido, universal). iFrame: se carga en un marco invisible (bueno para ocultar). Local: ofrece una página alojada localmente (mejor para embudos complejos).",
        "offerPostbackTooltip": "URL que envía la red de afiliados cuando se produce una conversión. Debe contener la macro de ID de clic (normalmente {subid} o {clickid}). Configure esta URL en el panel de control de la red de afiliados.",
        "postbackKeyTooltip": "Clave de seguridad agregada a la URL de devolución. Evita devoluciones de datos no autorizadas de terceros. Cámbiala si tu clave se ve comprometida.",
        "postbackAliasesTooltip": "Asignación de nombres de parámetros. Si una red envía 'clickid' en lugar de 'subid', agréguelo como alias. El rastreador aceptará ambos nombres de parámetros.",
        "indexCampaignTooltip": "Qué campaña mostrar cuando alguien visita el dominio raíz (por ejemplo, tudominio.com). Si no se establece, se muestra una página en blanco.",
        "httpsTooltip": "Redirige automáticamente todas las solicitudes HTTP a HTTPS. Recomendado por seguridad. Asegúrese de que su certificado SSL esté configurado.",
        "streamSchemaTooltip": "Configure qué ofertas y páginas de destino se muestran. Agregue varios elementos y establezca pesos para las pruebas A/B. La distribución total del peso se muestra arriba.",
        "streamFilterTooltip": "Establezca las condiciones en las que se debe activar esta transmisión: por país, dispositivo, sistema operativo, navegador, idioma, etc. El tráfico que no coincide con ninguna transmisión se dirige a la transmisión general.",
        "dismissAll": "Lo tengo",
        "showHelp": "Mostrar consejos"
    },
