        "oauthNotConfiguredHint": "El botón 1-Click necesita el App ID y App Secret de tu propia app de TikTok for Business (gratis — mira la guía de abajo). ¿No tienes app? Usa el botón «Conectar vía TikTok MCP»: no necesita ninguna app.",
        "tokenHowTo": "Guía de integración y claves de TikTok",
        "tokenHowToHint": "📌 Método 1: Conexión directa por token (requiere una app gratuita de TikTok — ver Método 2, paso 1):\n1. Cuando aprueben tu app, genera un Long-term Access Token en el Developer Portal (business-api.tiktok.com → tu app → Authorization). Ojo: un token de Events Manager NO sirve — solo envía eventos de conversión, no lee gastos.\n2. Copia el Advertiser ID (ID numérico en el menú de cuentas de ads.tiktok.com).\n3. Pega el Access Token y Advertiser ID abajo y pulsa «Probar conexión» → «Guardar».\n\n📌 Método 2: 1-Click OAuth (Detección automática de cuentas y píxeles):\n1. En el TikTok for Business Developer Portal (business-api.tiktok.com → Apps & Agents), regístrate como Direct Advertiser (gratis) y crea una app con permisos Ads Management + Reporting. La aprobación suele tardar de unas horas a un par de días.\n2. En Authorized Redirect URI, introduce la URL exacta del tracker (requiere HTTPS):\n{redirect_uri}\n3. Introduce el App ID y App Secret abajo (o en .env como ORBITRA_TIKTOK_APP_ID y ORBITRA_TIKTOK_APP_SECRET).\n4. Tras guardar, el botón 1-Click podrá abrir la ventana de login y conectar cuentas en 1 clic.",
