        "howToHint": "📌 Método 1: Conexión directa por token (Manual):\n1. Customer ID: Número de 10 dígitos en la esquina superior derecha de Google Ads (formato 123-456-7890).\n2. Developer Token: En tu cuenta Google Ads MCC → Herramientas y configuración → Centro de API (copia el token).\n3. Client ID y Client Secret: En Google Cloud Console (console.cloud.google.com) → APIs y servicios → Credenciales → Crear credenciales OAuth 2.0 (Aplicación web).\n4. Refresh Token: Token de acceso obtenido mediante OAuth Playground o asistente de autorización.\n5. Pega las claves abajo, pulsa «Probar conexión» y «Guardar».\n\n📌 Método 2: 1-Click OAuth (Detección automática de cuentas directas y MCC):\n1. En Google Cloud Console, añade esta URI de redirección autorizada exacta (requiere HTTPS):\n{redirect_uri}\n2. Guarda Developer Token, Client ID y Client Secret en el servidor (en .env o en el formulario de abajo).\n3. El botón 1-Click se activará para iniciar sesión con Google en 1 clic y seleccionar cuentas.",
